import { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  getDeviceInfo,
  updateGridStatus,
  DeviceManagementTypes
} from '@/apis/admin/device-management'
import { PageContainer, ProCard, ProDescriptions, ProTable } from '@ant-design/pro-components'
import {
  Button,
  message,
  Tag,
  Space,
  Spin,
  Badge,
  Popconfirm,
  Tooltip,
  Descriptions,
  Divider,
  Modal
} from 'antd'
import {
  ArrowLeftOutlined,
  InfoCircleOutlined,
  EnvironmentOutlined,
  ClockCircleOutlined,
  ThunderboltOutlined,
  AppstoreOutlined,
  UnlockOutlined,
  StopOutlined,
  CheckCircleOutlined,
  DesktopOutlined
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 格口规格映射
const gridSpecMap: Record<number, string> = {
  1: '小格',
  2: '中格',
  3: '大格'
}

// 格口规格颜色
const gridSpecColorMap: Record<number, string> = {
  1: '#52c41a',
  2: '#faad14',
  3: '#1890ff'
}

// 服务状态映射
const serviceStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '空闲', color: 'success' },
  2: { text: '占用', color: 'processing' },
  3: { text: '故障', color: 'error' },
  4: { text: '禁用', color: 'default' }
}

// 售货状态映射
const saleStatusMap: Record<number, string> = {
  1: '空置',
  2: '已补货',
  3: '已售出'
}

// 设备状态映射
const deviceStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '在线', color: 'success' },
  2: { text: '离线', color: 'error' },
  3: { text: '故障', color: 'warning' },
  4: { text: '未激活', color: 'default' }
}

const DeviceDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>()
  const navigate = useNavigate()
  const [deviceInfo, setDeviceInfo] = useState<DeviceManagementTypes.DeviceInfoDto | null>(null)
  const [loading, setLoading] = useState(true)

  // 获取设备详情
  const fetchDeviceInfo = async () => {
    if (!id) {
      return
    }
    try {
      setLoading(true)
      const res = await getDeviceInfo(Number(id))
      if (res.code === ResultEnum.SUCCESS && res.data?.list?.length > 0) {
        setDeviceInfo(res.data.list[0])
      } else {
        message.error('获取设备信息失败')
      }
    } catch (e) {
      console.error('获取设备详情失败:', e)
      message.error('获取设备详情失败')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    fetchDeviceInfo()
  }, [id])

  // 更新格口状态
  const handleUpdateGridStatus = async (gridId: number, status: number) => {
    try {
      const res = await updateGridStatus(gridId, {
        gridId,
        status: status as 1 | 2
      })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('格口状态更新成功')
        fetchDeviceInfo()
      } else {
        message.error('格口状态更新失败')
      }
    } catch (e) {
      console.error('更新格口状态失败:', e)
      message.error('格口状态更新失败')
    }
  }

  // 远程开门
  const handleRemoteOpen = (slot: DeviceManagementTypes.DeviceGridData) => {
    Modal.confirm({
      title: '远程开门确认',
      content: `确定要远程打开格口 ${slot.gridNo} 吗？`,
      onOk: () => {
        message.success(`格口 ${slot.gridNo} 远程开门指令已发送`)
      }
    })
  }

  // 计算格口统计
  const getSlotStats = (gridData: DeviceManagementTypes.DeviceGridData[]) => {
    const stats = {
      total: gridData.length,
      small: gridData.filter(g => g.spec === 1).length,
      medium: gridData.filter(g => g.spec === 2).length,
      big: gridData.filter(g => g.spec === 3).length,
      free: gridData.filter(g => g.serviceStatus === 1).length,
      occupied: gridData.filter(g => g.serviceStatus === 2).length,
      fault: gridData.filter(g => g.serviceStatus === 3).length,
      disabled: gridData.filter(g => g.serviceStatus === 4).length
    }
    return stats
  }

  if (loading) {
    return (
      <PageContainer>
        <div
          style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: 400 }}
        >
          <Spin size="large" tip="加载中..." />
        </div>
      </PageContainer>
    )
  }

  if (!deviceInfo) {
    return (
      <PageContainer>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <p>设备不存在或已被删除</p>
          <Button type="primary" onClick={() => navigate('/device/list')}>
            返回设备列表
          </Button>
        </div>
      </PageContainer>
    )
  }

  const { deviceBaseData, deviceGridData } = deviceInfo
  const slotStats = getSlotStats(deviceGridData)

  return (
    <PageContainer
      header={{
        title: (
          <Space>
            <Button
              type="text"
              icon={<ArrowLeftOutlined />}
              onClick={() => navigate('/device/list')}
            >
              返回列表
            </Button>
            <span style={{ fontSize: 20, fontWeight: 600 }}>设备详情</span>
          </Space>
        ),
        breadcrumb: undefined
      }}
    >
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        {/* 基本信息卡片 */}
        <ProCard
          title={
            <Space>
              <InfoCircleOutlined style={{ color: '#1890ff' }} />
              基本信息
            </Space>
          }
          bordered
          headerBordered
        >
          <ProDescriptions
            column={2}
            dataSource={deviceBaseData}
            columns={[
              {
                title: '设备编号',
                key: 'imei',
                dataIndex: 'imei',
                render: (text: any) => (
                  <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
                    {text as string}
                  </span>
                )
              },
              {
                title: '设备名称',
                key: 'deviceName',
                dataIndex: 'deviceName'
              },
              {
                title: '所属地区',
                key: 'areaName',
                dataIndex: 'areaName',
                render: (_: any, record: any) => (
                  <Space>
                    <EnvironmentOutlined style={{ color: '#1890ff' }} />
                    <span>
                      {record.provinceName}
                      {record.cityName}
                      {record.areaName}
                    </span>
                  </Space>
                )
              },
              {
                title: '小区',
                key: 'communityName',
                dataIndex: 'communityName',
                render: (text: any) => text || '-'
              },
              {
                title: '安装位置',
                key: 'installLocation',
                dataIndex: 'installLocation',
                render: (text: any) => text || '-'
              },
              {
                title: '设备型号',
                key: 'deviceModel',
                dataIndex: 'deviceModel'
              },
              {
                title: '激活时间',
                key: 'activeTime',
                dataIndex: 'activeTime',
                render: (text: any) => (
                  <Space>
                    <ThunderboltOutlined style={{ color: '#faad14' }} />
                    <span>{text || '-'}</span>
                  </Space>
                )
              },
              {
                title: '在线状态',
                key: 'deviceStatus',
                dataIndex: 'deviceStatus',
                render: (status: any) => (
                  <Badge
                    status={(deviceStatusMap[status as number]?.color as any) || 'default'}
                    text={deviceStatusMap[status as number]?.text || '未知'}
                  />
                )
              },
              {
                title: '最后心跳',
                key: 'lastHeartbeat',
                dataIndex: 'lastHeartbeat',
                render: (text: any) => (
                  <Space>
                    <ClockCircleOutlined style={{ color: '#52c41a' }} />
                    <span>{text || '-'}</span>
                  </Space>
                )
              },
              {
                title: '经纬度',
                key: 'longitude',
                dataIndex: 'longitude',
                render: (_: any, record: any) => (
                  <span style={{ fontFamily: 'Courier New, monospace', fontSize: 13 }}>
                    {record.longitude}, {record.latitude}
                  </span>
                )
              }
            ]}
          />
        </ProCard>

        {/* 格口明细卡片 */}
        <ProCard
          title={
            <Space>
              <AppstoreOutlined style={{ color: '#1890ff' }} />
              格口明细
              <Space size="small" style={{ marginLeft: 16 }}>
                <Tag color="blue">
                  <DesktopOutlined /> 主柜 × 1
                </Tag>
                <span style={{ fontSize: 13, color: '#666' }}>
                  共 {slotStats.total} 个格口（小{slotStats.small} / 中{slotStats.medium} / 大
                  {slotStats.big}）
                </span>
              </Space>
            </Space>
          }
          bordered
          headerBordered
        >
          <ProTable<DeviceManagementTypes.DeviceGridData>
            columns={[
              {
                title: '格口编号',
                key: 'gridNo',
                dataIndex: 'gridNo',
                width: 100,
                render: (text: any) => (
                  <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 600 }}>
                    {text as string}
                  </span>
                )
              },
              {
                title: '所属柜子',
                key: 'gridType',
                dataIndex: 'gridType',
                width: 100,
                render: () => <Tag color="blue">主柜</Tag>
              },
              {
                title: '规格',
                key: 'spec',
                dataIndex: 'spec',
                width: 80,
                render: (spec: any) => (
                  <Tag color={gridSpecColorMap[spec as number]}>{gridSpecMap[spec as number]}</Tag>
                )
              },
              {
                title: '服务状态',
                key: 'serviceStatus',
                dataIndex: 'serviceStatus',
                width: 100,
                render: (status: any) => {
                  const s = serviceStatusMap[status as number]
                  return <Badge status={s.color as any} text={s.text} />
                }
              },
              {
                title: '售货状态',
                key: 'saleStatus',
                dataIndex: 'saleStatus',
                width: 100,
                render: (status: any) => saleStatusMap[status as number] || '-'
              },
              {
                title: '当前商品',
                key: 'goodsName',
                dataIndex: 'goodsName',
                width: 140,
                render: (text: any, record: any) => (
                  <span style={{ fontSize: 13 }}>
                    {text || '-'}
                    {record.goodsId ? (
                      <span style={{ color: '#999', marginLeft: 4 }}>(ID: {record.goodsId})</span>
                    ) : null}
                  </span>
                )
              },
              {
                title: '当前订单号',
                key: 'orderNo',
                dataIndex: 'orderNo',
                width: 160,
                render: (text: any) => (
                  <span style={{ fontFamily: 'Courier New, monospace', fontSize: 12 }}>
                    {text || '-'}
                  </span>
                )
              },
              {
                title: '存件时间',
                key: 'storeTime',
                dataIndex: 'storeTime',
                width: 160,
                render: (time: any) => {
                  if (!time) {
                    return '-'
                  }
                  const date = new Date(time * 1000)
                  return (
                    <span style={{ fontSize: 13, color: '#666' }}>{date.toLocaleString()}</span>
                  )
                }
              },
              {
                title: '操作',
                key: 'option',
                fixed: 'right',
                width: 180,
                render: (_: any, record: any) => (
                  <Space>
                    <Button
                      type="link"
                      size="small"
                      icon={<UnlockOutlined />}
                      onClick={() => handleRemoteOpen(record)}
                    >
                      远程开门
                    </Button>
                    {record.serviceStatus === 1 && (
                      <Popconfirm
                        title="确定要禁用该格口吗？"
                        onConfirm={() => handleUpdateGridStatus(record.gridId, 2)}
                      >
                        <Button type="link" danger size="small" icon={<StopOutlined />}>
                          禁用
                        </Button>
                      </Popconfirm>
                    )}
                    {record.serviceStatus === 4 && (
                      <Button
                        type="link"
                        size="small"
                        icon={<CheckCircleOutlined />}
                        style={{ color: '#52c41a' }}
                        onClick={() => handleUpdateGridStatus(record.gridId, 1)}
                      >
                        启用
                      </Button>
                    )}
                  </Space>
                )
              }
            ]}
            dataSource={deviceGridData}
            rowKey="gridId"
            pagination={{ pageSize: 10 }}
            search={false}
            options={false}
            scroll={{ x: 1000 }}
            size="small"
          />
        </ProCard>

        {/* 格口统计卡片 */}
        <ProCard
          title={
            <Space>
              <DesktopOutlined style={{ color: '#1890ff' }} />
              格口统计
            </Space>
          }
          bordered
          headerBordered
        >
          <Descriptions column={4} bordered size="small">
            <Descriptions.Item label="总格口数">{slotStats.total}</Descriptions.Item>
            <Descriptions.Item label="小格">{slotStats.small}</Descriptions.Item>
            <Descriptions.Item label="中格">{slotStats.medium}</Descriptions.Item>
            <Descriptions.Item label="大格">{slotStats.big}</Descriptions.Item>
            <Descriptions.Item label="空闲">
              <Badge status="success" text={slotStats.free} />
            </Descriptions.Item>
            <Descriptions.Item label="占用">
              <Badge status="processing" text={slotStats.occupied} />
            </Descriptions.Item>
            <Descriptions.Item label="故障">
              <Badge status="error" text={slotStats.fault} />
            </Descriptions.Item>
            <Descriptions.Item label="禁用">
              <Badge status="default" text={slotStats.disabled} />
            </Descriptions.Item>
          </Descriptions>
        </ProCard>
      </Space>
    </PageContainer>
  )
}

export default DeviceDetail
